namespace Garbati.OpsApi.Clients.Contracts.Orchestrator;

// Mirrors Garbati.OrchestratorApi.Contracts.Requests.StartAccountOpeningRequest. IdempotencyKey is
// generated by OpsApi itself (the browser has no natural idempotency-key concept), not accepted from the
// testing console's form.
public record StartAccountOpeningRequest(
    string IdempotencyKey,
    string FullName,
    string JurisdictionCode,
    string? CustomerReference,
    string? Email,
    string? PhoneNumber,
    string AccountName,
    string AccountType,
    string CurrencyCode);
